# desk/advances.keel
module desk.advances
import desk.ids as ids
import desk.records as records
import desk.reports as reports

interface
  type AdvanceId = Text

  machine AdvanceStatus
    states  Requested, Approved, Paid, Settled
    initial Requested
    Requested enters Approved
    Approved  enters Paid
    Paid      enters Settled

  type Advance = { id: AdvanceId, badge: ids.Badge, department: ids.DepartmentId, period: ids.Period, amount: records.Amount, status: AdvanceStatus, approvals: reports.Approvals }
    where status in {AdvanceStatus.Paid, AdvanceStatus.Settled} has reference: Text
    where status in {AdvanceStatus.Settled} has owed: Int
  type Advances = Array<Advance> where length in 0 to 1000

  type Requested = Advance where status in {AdvanceStatus.Requested}
  type Approved  = Advance where status in {AdvanceStatus.Approved}
  type Paid      = Advance where status in {AdvanceStatus.Paid}
  type Counted   = Advance where status in {AdvanceStatus.Approved, AdvanceStatus.Paid}

  fn add_approval(a: Requested, who: ids.Badge) -> Advance
    before a.approvals.length < 2
    after  result.status in {AdvanceStatus.Requested} and result.approvals.length == a.approvals.length + 1
  fn approve(a: Requested) -> Advance
    after result.status in {AdvanceStatus.Approved}
  fn pay(a: Approved, reference: Text) -> Advance
    after result.status in {AdvanceStatus.Paid}
  fn settle(a: Paid, owed: Int) -> Advance
    before owed >= 0
    after  result.status in {AdvanceStatus.Settled} and result.owed == owed
body
  fn add_approval(a, who) = a with { approvals: a.approvals ++ [who] }
  fn approve(a)           = a with { status enters AdvanceStatus.Approved }
  fn pay(a, reference)    = a with { status enters AdvanceStatus.Paid, reference: reference }
  fn settle(a, owed)      = a with { status enters AdvanceStatus.Settled, owed: owed }

