    let others: reports.Reports = store.reports_for(a.department, a.period)?
    let adv: advances.Advances = store.advances_for(a.department, a.period)?
    let within: Bool = budget.spend_of(others, adv) + a.amount <= dept.budget
    if within or who.role in {ids.Role.Finance} then
